/* 소제목에는 번호를 붙이지 않는다. 단계 표시는 flowBlock·stepList 의 ①② 로만 한다 */
const CIRC = "①②③④⑤⑥⑦⑧⑨⑩⑪⑫";
function hN(i, t){ return "<h2>"+t+"</h2>"; }
function summaryBox(items){
  return "<div class='ansbox sumbox'><div class=ansbox-t>📌 한눈에 보기</div><ul class=sumlist>"+
    items.map(function(x){ return "<li><span class=ok>✓</span><span>"+x+"</span></li>"; }).join("")+"</ul></div>";
}
function statMini(items){
  return "<div class=smini>"+items.map(function(x){ return "<div class=sm><div class=sm-n>"+x[0]+"</div><div class=sm-c>"+x[1]+"</div></div>"; }).join("")+"</div>";
}
function flowBlock(steps){
  return "<div class=flow role=list>"+steps.map(function(s,i){
    return (i?"<span class=farr aria-hidden=true>→</span>":"")+"<div class=fstep role=listitem><span class=fnum>"+CIRC[i]+"</span><b>"+s[0]+"</b><i>"+s[1]+"</i></div>"; }).join("")+"</div>";
}
function stepList(steps){
  return "<ol class=steps>"+steps.map(function(s,i){ return "<li><span class=sn2>"+CIRC[i]+"</span><div><b>"+s[0]+"</b><p>"+s[2]+"</p></div></li>"; }).join("")+"</ol>";
}
function checklist(title, items){
  return "<div class=chk><div class=chk-t>"+title+"</div><div class=chk-g>"+
    items.map(function(x){ return "<div class=chk-i><span class=ck>✓</span><span>"+x+"</span></div>"; }).join("")+"</div></div>";
}
function callout(k, html){ return "<div class=callout><span class=co-k>"+k+"</span><p>"+html+"</p></div>"; }
function eqCards(cards){
  return "<div class=eqgrid>"+cards.map(function(c,i){
    return "<div class=eq id=eq-"+(i+1)+"><div class=eq-h><span class=eq-i aria-hidden=true>"+c.ico+"</span><b>"+esc(c.name)+"</b><em>"+c.badge+"</em></div>"+
      "<dl>"+c.rows.map(function(r){ return "<dt>"+r[0]+"</dt><dd>"+esc(r[1])+"</dd>"; }).join("")+"</dl></div>"; }).join("")+"</div>";
}
function thumbFig(key, alt){
  return "<figure class=thumb><img src=\"/og/"+key+"-1200.webp\" srcset=\"/og/"+key+"-600.webp 600w, /og/"+key+"-1200.webp 1200w\" sizes=\"(max-width:768px) 100vw, 720px\" width=\"1200\" height=\"630\" alt=\""+esc(alt)+"\" fetchpriority=\"high\" decoding=\"async\"></figure>";
}
function thumbPreload(key){ return {href:"/og/"+key+"-1200.webp", srcset:"/og/"+key+"-600.webp 600w, /og/"+key+"-1200.webp 1200w", sizes:"(max-width:768px) 100vw, 720px"}; }
function ogPng(key){ return SITE+"/og/"+key+".png"; }

