    cost:[["진료 프로그램 연동","쓰는 진료 프로그램과 연동되는 기종으로 골라야 하고, 연동 설정 작업이 필요할 수 있습니다."],["창구 수","수납 창구가 늘면 창구마다 단말기와 프린터가 필요합니다."],["판매 관리 기능","상품 재고·매출 관리 기능이 있는 포스 프로그램은 월 이용료가 붙는 경우가 있습니다."],["계약 방식","구매, 렌탈, 밴(VAN)사 약정 설치 가운데 무엇을 고르냐에 따라 초기 비용과 월 비용이 달라집니다."],["주변기기","바코드 스캐너, 대기 번호 화면처럼 붙는 장비에 따라 초기 비용이 달라집니다."]],
    costText:"병의원 포스기 비용은 장비보다 연동 범위에서 크게 갈립니다. 진료 프로그램과 결제 단말기만 이으면 되는 곳과, 판매 상품을 포스로 따로 관리하고 창구가 여럿인 곳은 필요한 구성이 전혀 다릅니다. 견적을 받기 전에 쓰는 진료 프로그램 이름과 창구 수, 판매 상품 여부를 먼저 정리해 두세요.",
    steps:[["프로그램 확인","진료 프로그램 이름","쓰고 있거나 쓸 예정인 진료 프로그램과 연동 가능한 결제 기종을 확인합니다."],["역할 나누기","진료비와 상품","진료비는 진료 프로그램에서, 판매 상품은 포스에서 받을지 등 수납 경로를 정합니다."],["가맹·등록","개설 서류","사업자등록증과 의료기관 개설 서류로 카드 가맹을 신청하고, 기존 가맹이면 단말기만 등록합니다."],["방문 설치","창구 배치","수납 창구에 단말기와 프린터를 두고 진료 프로그램 연동과 판매 상품 등록을 진행합니다."],["수납 테스트","연동·취소 확인","진료 프로그램에서 금액을 넘겨 실제 카드로 결제·취소해 보고 수납 기록이 맞게 남는지 확인합니다."]],
    check:["쓰는 진료 프로그램 이름을 확인했나요?","진료비와 판매 상품의 수납 경로를 나눴나요?","수납 창구가 몇 곳인지 정했나요?","판매 상품에 바코드가 있나요?","현금영수증 발행 방식을 정했나요?","카드 두 장으로 나눠 받는 방법을 알고 있나요?","의료기관 개설 서류를 준비했나요?","진료가 없는 시간에 설치할 수 있나요?"],
    faq:[
      ["병의원 포스기와 진료 프로그램을 같이 쓸 수 있나요?","같이 쓰는 경우가 많습니다. 진료비는 진료 프로그램에서, 판매 상품은 포스에서 받도록 나누고, 결제 단말기가 양쪽에 연동되는지 확인합니다."],
      ["판매하는 건강기능식품 재고도 관리되나요?","상품을 포스에 등록하고 입고 수량을 넣어 두면 판매할 때마다 재고가 줄어듭니다. 바코드가 있는 상품은 스캐너로 찍어 등록하면 빠릅니다."],
      ["포스로 하루 수납 마감을 할 수 있나요?","포스에서 받은 판매 매출은 포스에서 마감하고, 진료비 수납은 진료 프로그램에서 마감합니다. 두 마감을 합쳐 볼 방법이 필요하면 설치 전에 상의합니다."],
      ["환자가 카드 두 장으로 나눠 내면 어떻게 하나요?","한 건의 금액을 나눠 카드별로 결제받는 분할 결제 방법이 있습니다. 진료 프로그램에서 처리하는지 포스에서 처리하는지에 따라 순서가 달라 설치 때 안내합니다."],
      ["개원 전에 포스기를 미리 설치해도 되나요?","장비 설치와 연동 설정은 미리 해 두고, 카드 가맹이 나면 실제 결제 테스트를 합니다. 개원일 전에 테스트를 마치는 일정으로 잡는 것이 좋습니다."],
      ["진료 프로그램을 바꾸면 포스도 바꿔야 하나요?","포스 자체는 그대로 쓸 수 있는 경우가 많지만, 결제 단말기가 새 진료 프로그램과 연동되는지는 다시 확인해야 합니다."]]
