const FIXED = ["/about","/cost","/install","/faq","/contact","/privacy","/terms"];
function pageUrls(){
  const u=[SITE+"/"];
  for (const p of PROD_KEYS) u.push(SITE+"/"+p);
  for (const b of BIZ){ u.push(SITE+bizUrl(b)); for (const p of PROD_KEYS) u.push(SITE+bizUrl(b,p)); }
  for (const f of FIXED) u.push(SITE+f);
  return u;
}
const XMLHEAD = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>";
/* 단일 urlset. lastmod 는 실제로 고친 날(CONTENT_DATE)과 글 발행일만 쓴다. */
function sitemapAll(){
  let u=XMLHEAD+"<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">";
  for (const x of pageUrls()) u+="<url><loc>"+x+"</loc><lastmod>"+CONTENT_DATE+"</lastmod></url>";
  const ps=POSTS_CACHE.rows||[];
  if (ps.length){
    u+="<url><loc>"+POST_ORIGIN+"/post/</loc><lastmod>"+postDate(ps[0])+"</lastmod></url>";
    for (const p of ps) u+="<url><loc>"+POST_ORIGIN+"/post/"+p.slug+"/</loc><lastmod>"+postDate(p)+"</lastmod></url>";
  }
  return u+"</urlset>";
}
function rssFeed(){
  const ps=POSTS_CACHE.rows||[];
  let x=XMLHEAD+'<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom"><channel>';
  x+='<title>'+BRAND+' — 포스기 정보</title><link>'+SITE+'/post/</link>';
  x+='<atom:link href="'+SITE+'/rss.xml" rel="self" type="application/rss+xml"/>';
  x+='<description>포스기·카드단말기·무선단말기를 들이고 쓰는 데 필요한 정보.</description><language>ko</language>';
  if (ps.length) x+='<lastBuildDate>'+new Date(ps[0].published_at).toUTCString()+'</lastBuildDate>';
  for (const p of ps){
    const u=POST_ORIGIN+'/post/'+postEsc(p.slug)+'/';
    x+='<item><title>'+postEsc(p.title)+'</title><link>'+u+'</link><guid isPermaLink="true">'+u+'</guid>'
      +'<pubDate>'+new Date(p.published_at).toUTCString()+'</pubDate><description>'+postEsc(p.summary||p.title)+'</description></item>';
  }
  return x+'</channel></rss>';
}
function atomFeed(){
  const ps=POSTS_CACHE.rows||[];
  let x=XMLHEAD+'<feed xmlns="http://www.w3.org/2005/Atom" xml:lang="ko">';
  x+='<title>'+esc(BRAND)+' — 포스기 정보</title><link href="'+SITE+'/post/"/><link href="'+SITE+'/atom.xml" rel="self"/><id>'+SITE+'/post/</id>';
  x+='<updated>'+(ps.length?new Date(ps[0].published_at).toISOString():CONTENT_DATE+"T00:00:00Z")+'</updated>';
  for (const p of ps){
    const u=POST_ORIGIN+'/post/'+postEsc(p.slug)+'/';
    x+='<entry><title>'+postEsc(p.title)+'</title><link href="'+u+'"/><id>'+u+'</id><updated>'+new Date(p.published_at).toISOString()+'</updated><summary>'+postEsc(p.summary||p.title)+'</summary></entry>';
  }
  return x+'</feed>';
}
