function resp(html,type,extra){
  return new Response(html,{headers:Object.assign({"content-type":type,"cache-control":"public, max-age=600"},extra||{})});
}
function moved(path){ return new Response(null,{status:301,headers:{"location":SITE+path,"cache-control":"public, max-age=86400"}}); }

/* 새 페이지 라우팅 — 있으면 HTML, 없으면 null */
function renderPage(path){
  if(path==="/") return homePage();
  if(PAGES[path]) return PAGES[path]();
  const seg=path.split("/");               // ["", 제품|biz, 업종]
  if(seg.length===2 && PROD[seg[1]]) return productPage(seg[1]);
  if(seg.length===3){
    const b=BIZ_BY.get(seg[2]); if(!b) return null;
    if(PROD[seg[1]]) return bizProductPage(b, seg[1]);
    if(seg[1]==="biz") return bizHubPage(b);
  }
  return null;
}
/* 옛 주소 → 새 주소 (3차 재구성, 2026-09-30).
   시·도×제품·무선단말기·옛 /r·/card·/sigungu·/sido 는 모두 해당 제품 페이지로 모은다. */
function legacyTarget(path){
  const seg=path.split("/"), k=seg[1];
  if(k==="wireless-terminal") return "/card-terminal";
  if(seg.length<3 || !seg[2]) return null;
  if(k==="r"||k==="sigungu"||k==="sido") return "/pos";
  if(k==="card") return "/card-terminal";
  if((k==="pos"||k==="card-terminal") && seg.length===3 && SIDO_BY_S.has(seg[2])) return "/"+k;
  return null;
}
